INSERT INTO public.tours (id, owner_id, name, slug, description, category, city_code, region_code, location, meeting_point, duration_hours, currency, price, max_participants, contact_phone, contact_whatsapp, contact_instagram, main_image_url, status, is_demo, rating, review_count, view_count)
VALUES
('22222222-2222-4222-8222-000000000004', NULL, 'Tatev Monastery & Wings of Tatev', 'tatev-monastery-wings', 'Ride the world''s longest reversible aerial tramway — the Wings of Tatev — soaring above the Vorotan Gorge to reach the 9th-century Tatev Monastery. Walk the ancient grounds, learn about the scholars who studied here, and take in one of Armenia''s most breathtaking panoramic views.', 'monastery', 'tatev', 'syunik', 'Tatev', 'Wings of Tatev lower station, Halidzor', 9, 'AMD', 22000, 15, '+37499999994', '+37499999994', 'hyur.tours', '/images/demo/tour-monastery.jpg', 'APPROVED', true, 4.95, 87, 312),
('22222222-2222-4222-8222-000000000005', NULL, 'Garni & Geghard Cultural Day Trip', 'garni-geghard-cultural', 'Visit the only surviving Greco-Roman pagan temple in Armenia at Garni, then continue to the rock-carved Geghard Monastery — a UNESCO World Heritage Site partially cut into the mountain. A journey through 2000 years of Armenian history.', 'cultural', 'garni', 'kotayk', 'Garni', 'Garni Temple entrance', 6, 'AMD', 18000, 20, '+37499999995', '+37499999995', 'hyur.tours', '/images/demo/tour-monastery.jpg', 'APPROVED', true, 4.85, 52, 198),
('22222222-2222-4222-8222-000000000006', NULL, 'Vayots Dzor Jeep Adventure', 'vayots-dzor-jeep-adventure', 'Off-road through the dramatic landscapes of Vayots Dzor — volcanic plateaus, hidden caves, and mountain passes that regular cars cannot reach. Includes a stop at the Areni-1 cave complex where the world''s oldest winery was discovered.', 'jeep', 'areni', 'vayots-dzor', 'Vayots Dzor', 'Areni village center', 8, 'AMD', 35000, 8, '+37499999996', '+37499999996', 'hyur.tours', '/images/demo/tour-jeep.jpg', 'APPROVED', true, 4.90, 34, 156),
('22222222-2222-4222-8222-000000000007', NULL, 'Armenian Cooking Class in a Village Home', 'armenian-cooking-class', 'Learn to prepare traditional Armenian dishes — tolma, khorovats, and lavash — in a family kitchen in a highland village. Roll up your sleeves, cook alongside local women, then enjoy the feast together with homemade wine.', 'cooking', 'dilijan', 'tavush', 'Dilijan', 'Dilijan old town, Hovhannes Tumanyan street', 4, 'AMD', 20000, 10, '+37499999997', '+37499999997', 'hyur.tours', '/images/demo/tour-food.jpg', 'APPROVED', true, 4.88, 41, 142),
('22222222-2222-4222-8222-000000000008', NULL, 'Debed River Rafting', 'debed-river-rafting', 'An exhilarating half-day rafting trip on the Debed River in Lori — calm stretches for beginners and exciting rapids for thrill-seekers. All equipment and certified guides included. No experience necessary.', 'rafting', 'stepanavan', 'lori', 'Stepanavan', 'Debed Canyon bridge, Sanahin', 5, 'AMD', 28000, 12, '+37499999998', '+37499999998', 'hyur.tours', '/images/demo/tour-rafting.jpg', 'APPROVED', true, 4.75, 23, 98),
('22222222-2222-4222-8222-000000000009', NULL, 'Tsaghkadzor Horseback Riding', 'tsaghkadzor-horseback', 'Ride through alpine meadows and pine forests around Tsaghkadzor on horseback. Suitable for beginners and experienced riders alike. Includes a stop at a mountain spring for a picnic lunch.', 'horse_riding', 'tsaghkadzor', 'kotayk', 'Tsaghkadzor', 'Tsaghkadzor ropeway base', 3, 'AMD', 16000, 8, '+37499999999', '+37499999999', 'hyur.tours', '/images/demo/tour-horse.jpg', 'APPROVED', true, 4.82, 29, 112),
('22222222-2222-4222-8222-000000000010', NULL, 'Mount Aragats Stargazing Camp', 'aragats-stargazing-camp', 'Camp at 3200m on the southern slopes of Mount Aragats, Armenia''s highest peak. Watch the sunset paint the four peaks, enjoy a campfire dinner, then stargaze under one of the darkest skies in the Caucasus. Tents and sleeping bags provided.', 'camping', 'garni', 'aragatsotn', 'Aragats', 'Ashtarak-Byurakan highway, Lake Kari', 12, 'AMD', 40000, 6, '+37499999990', '+37499999990', 'hyur.tours', '/images/demo/tour-camping.jpg', 'APPROVED', true, 4.93, 38, 167),
('22222222-2222-4222-8222-000000000011', NULL, 'Sevan Fisherman''s Morning', 'sevan-fishermans-morning', 'Wake before dawn and join a local fisherman on Lake Sevan — Armenia''s alpine jewel. Cast nets and lines, learn traditional fishing techniques, and grill your catch on the shore for breakfast with fresh lavash and herbs.', 'fishing', 'sevan', 'gegharkunik', 'Sevan', 'Sevan peninsula, North shore', 5, 'AMD', 19000, 6, '+37499999991', '+37499999991', 'hyur.tours', '/images/demo/tour-photo.jpg', 'APPROVED', true, 4.65, 15, 76),
('22222222-2222-4222-8222-000000000012', NULL, 'Yerevan Food & Wine Walk', 'yerevan-food-wine-walk', 'A walking food tour through Yerevan''s backstreets — taste khorovats at a hidden grill, sample craft wine from a local cellar, finish with Armenian brandy and pakhlava at a rooftop café. Six tastings included.', 'food', 'yerevan', 'yerevan', 'Yerevan', 'Republic Square fountain, Yerevan', 4, 'AMD', 16000, 12, '+37499999992', '+37499999992', 'hyur.tours', '/images/demo/tour-food.jpg', 'APPROVED', true, 4.91, 64, 234)
